export class MergePayError extends Error {
    code;
    category;
    cause;
    constructor(input) {
        super(input.message);
        this.name = "MergePayError";
        this.code = input.code;
        this.category = input.category;
        if (input.cause !== undefined) {
            this.cause = input.cause;
        }
    }
    toPublic() {
        return { code: this.code, message: this.message };
    }
}
